import{_ as d,C as l,o as r,c as T,a2 as s,b as o,w as a,a as e,E,a3 as A}from"./chunks/framework.BC3NdntU.js";const S=JSON.parse('{"title":"4.4 HTTPS 与 TLS","description":"","frontmatter":{},"headers":[],"relativePath":"卷四-网络与通信/4.4-HTTPS与TLS.md","filePath":"卷四-网络与通信/4.4-HTTPS与TLS.md","lastUpdated":1788919885000}'),i={name:"卷四-网络与通信/4.4-HTTPS与TLS.md"};function p(h,t,C,g,B,u){const n=l("Mermaid");return r(),T("div",null,[t[3]||(t[3]=s('<h1 id="_4-4-https-与-tls" tabindex="-1">4.4 HTTPS 与 TLS <a class="header-anchor" href="#_4-4-https-与-tls" aria-label="Permalink to &quot;4.4 HTTPS 与 TLS&quot;">​</a></h1><blockquote><p>卷:卷四 · 网络与通信 阅读时间:30min</p></blockquote><hr><h2 id="引言-http-为什么-裸奔-https-加了三把锁" tabindex="-1">引言:HTTP 为什么&quot;裸奔&quot;,HTTPS 加了三把锁 <a class="header-anchor" href="#引言-http-为什么-裸奔-https-加了三把锁" aria-label="Permalink to &quot;引言:HTTP 为什么&quot;裸奔&quot;,HTTPS 加了三把锁&quot;">​</a></h2><p>HTTP 明文传输,有三大风险:<strong>窃听、篡改、冒充</strong>。HTTPS = HTTP + TLS,用「加密」防窃听、「完整性校验」防篡改、「证书」防冒充。深挖要懂<strong>混合加密</strong>与<strong>中间人攻击为何被证书链挡下</strong>。</p><hr><h2 id="一、三风险-→-三对策" tabindex="-1">一、三风险 → 三对策 <a class="header-anchor" href="#一、三风险-→-三对策" aria-label="Permalink to &quot;一、三风险 → 三对策&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风险</th><th>HTTPS 对策</th></tr></thead><tbody><tr><td>窃听(明文被抓)</td><td><strong>对称加密</strong></td></tr><tr><td>篡改(内容被改)</td><td><strong>完整性校验</strong>(MAC/摘要)</td></tr><tr><td>冒充(无法验身份)</td><td><strong>证书 + 非对称加密</strong></td></tr></tbody></table><hr><h2 id="二、两种加密-混合" tabindex="-1">二、两种加密 + 混合 <a class="header-anchor" href="#二、两种加密-混合" aria-label="Permalink to &quot;二、两种加密 + 混合&quot;">​</a></h2>',10)),(r(),o(A,null,{default:a(()=>[E(n,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E9%9D%9E%E5%AF%B9%E7%A7%B0%E5%8A%A0%E5%AF%86%20RSA%2FECDHE%3Cbr%2F%3E%E6%85%A2%2C%E5%85%AC%E9%92%A5%2F%E7%A7%81%E9%92%A5%E5%AF%B9%5D%20--%3E%7C%E5%8F%AA%E7%94%A8%E6%9D%A5%E4%BA%A4%E6%8D%A2%7C%20B%5B%E5%AF%B9%E7%A7%B0%E5%AF%86%E9%92%A5%5D%0A%20%20%20%20B%20--%3E%20C%5B%E5%AF%B9%E7%A7%B0%E5%8A%A0%E5%AF%86%20AES%3Cbr%2F%3E%E5%BF%AB%2C%E5%8A%A0%E5%AF%86%E6%95%B0%E6%8D%AE%E6%9C%AC%E4%BD%93%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[e(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=s('<table tabindex="0"><thead><tr><th></th><th>对称</th><th>非对称</th></tr></thead><tbody><tr><td>密钥</td><td>一把(同钥加解密)</td><td>一对(公/私)</td></tr><tr><td>速度</td><td><strong>快</strong></td><td>慢</td></tr><tr><td>用途</td><td>加密数据</td><td>交换密钥、验签名</td></tr></tbody></table><p><strong>为什么混合?</strong> 非对称慢、扛不住大流量;纯对称密钥分发不安全(明文发=没加密)。所以:<strong>非对称交换对称密钥(少量数据)→ 对称加密数据(大量数据)</strong>。</p><hr><h2 id="三、证书链-防冒充的根基" tabindex="-1">三、证书链:防冒充的根基 <a class="header-anchor" href="#三、证书链-防冒充的根基" aria-label="Permalink to &quot;三、证书链:防冒充的根基&quot;">​</a></h2>',4)),(r(),o(A,null,{default:a(()=>[E(n,{id:"mermaid-119",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E6%9C%8D%E5%8A%A1%E5%99%A8%E8%AF%81%E4%B9%A6%5D%20--%3E%7C%E7%94%B1%7C%20B%5B%E4%B8%AD%E9%97%B4%20CA%20%E7%AD%BE%E5%8F%91%5D%0A%20%20%20%20B%20--%3E%7C%E7%94%B1%7C%20C%5B%E6%A0%B9%20CA%20%E7%AD%BE%E5%8F%91%5D%0A%20%20%20%20C%20--%3E%7C%E5%86%85%E7%BD%AE%E5%9C%A8%7C%20D%5B%E6%B5%8F%E8%A7%88%E5%99%A8%E4%BF%A1%E4%BB%BB%E5%BA%93%5D%0A"})]),fallback:a(()=>[...t[1]||(t[1]=[e(" Loading... ",-1)])]),_:1})),t[5]||(t[5]=s('<ul><li>证书 = &quot;域名 + 该域名公钥 + 签发者签名&quot;</li><li>浏览器用<strong>内置根 CA 公钥</strong>逐级验签,确认&quot;公钥确实属于该域名&quot;</li></ul><p><strong>中间人攻击(MITM)为何被挡下?</strong></p><blockquote><p>攻击者想伪装成服务器:① 自建证书 → 浏览器因<strong>根 CA 不信任</strong>而告警;② 篡改真证书 → <strong>签名校验不通过</strong>;③ 冒充域名 → 拿不到该域名的合法证书。三者全堵死,这就是证书链 + CA 的价值。</p></blockquote><hr><h2 id="四、tls-握手-简版" tabindex="-1">四、TLS 握手(简版) <a class="header-anchor" href="#四、tls-握手-简版" aria-label="Permalink to &quot;四、TLS 握手(简版)&quot;">​</a></h2>',5)),(r(),o(A,null,{default:a(()=>[E(n,{id:"mermaid-144",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20C%20as%20%E5%AE%A2%E6%88%B7%E7%AB%AF%0A%20%20%20%20participant%20S%20as%20%E6%9C%8D%E5%8A%A1%E5%99%A8%0A%20%20%20%20C-%3E%3ES%3A%20ClientHello(%E7%89%88%E6%9C%AC%E3%80%81%E5%8A%A0%E5%AF%86%E5%A5%97%E4%BB%B6%E3%80%81%E9%9A%8F%E6%9C%BA%E6%95%B0)%0A%20%20%20%20S--%3E%3EC%3A%20ServerHello(%E9%80%89%E5%AE%9A%E5%A5%97%E4%BB%B6%E3%80%81%E9%9A%8F%E6%9C%BA%E6%95%B0)%2B%20%E8%AF%81%E4%B9%A6%0A%20%20%20%20Note%20over%20C%3A%20%E9%AA%8C%E8%AF%81%E4%B9%A6%20%E2%86%92%20%E7%94%9F%E6%88%90%E9%A2%84%E5%A4%87%E4%B8%BB%E5%AF%86%E9%92%A5%0A%20%20%20%20C-%3E%3ES%3A%20%E5%AF%86%E9%92%A5%E4%BA%A4%E6%8D%A2%E5%8F%82%E6%95%B0(%E5%85%AC%E9%92%A5%E5%8A%A0%E5%AF%86)%0A%20%20%20%20Note%20over%20C%2CS%3A%20%E5%8F%8C%E6%96%B9%E7%AE%97%E5%87%BA%E4%BC%9A%E8%AF%9D%E5%AF%86%E9%92%A5%0A%20%20%20%20C-%3E%3ES%3A%20Finished(%E5%AF%B9%E7%A7%B0%E5%8A%A0%E5%AF%86)%0A%20%20%20%20S--%3E%3EC%3A%20Finished(%E6%8F%A1%E6%89%8B%E5%AE%8C%E6%88%90%2C%E8%BF%9B%E5%85%A5%E5%AF%B9%E7%A7%B0%E5%8A%A0%E5%AF%86)%0A"})]),fallback:a(()=>[...t[2]||(t[2]=[e(" Loading... ",-1)])]),_:1})),t[6]||(t[6]=s(`<blockquote><p><strong>先验证书(防冒充)→ 非对称交换密钥(防窃听)→ 对称加密通信(快)</strong>。</p></blockquote><hr><h2 id="五、http-1-1-→-2-→-3" tabindex="-1">五、HTTP/1.1 → 2 → 3 <a class="header-anchor" href="#五、http-1-1-→-2-→-3" aria-label="Permalink to &quot;五、HTTP/1.1 → 2 → 3&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>改进</th><th>痛点</th></tr></thead><tbody><tr><td>HTTP/1.1</td><td>持久连接</td><td>队头阻塞、串行</td></tr><tr><td>HTTP/2</td><td><strong>多路复用</strong>、头部压缩、二进制分帧</td><td>底层 TCP,丢包仍阻塞</td></tr><tr><td>HTTP/3</td><td>基于 <strong>QUIC(UDP)</strong>、0-RTT、根治队头阻塞</td><td>新、中间设备适配</td></tr></tbody></table><hr><h2 id="六、小结" tabindex="-1">六、小结 <a class="header-anchor" href="#六、小结" aria-label="Permalink to &quot;六、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTPS = HTTP + TLS</span></span>
<span class="line"><span>三对策:对称加密(防窃听)+ 完整性校验(防篡改)+ 证书/CA(防冒充)</span></span>
<span class="line"><span>混合加密:非对称换对称密钥 → 对称传数据</span></span>
<span class="line"><span>证书链:服务器证书→中间CA→根CA(浏览器信任);MITM 被三路堵死</span></span>
<span class="line"><span>演进:1.1(持久)→2(多路复用)→3(QUIC/UDP)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><hr><h2 id="七、面试题" tabindex="-1">七、面试题 <a class="header-anchor" href="#七、面试题" aria-label="Permalink to &quot;七、面试题&quot;">​</a></h2><p><strong>Q1:为什么 HTTPS 用&quot;混合加密&quot;而非纯对称/纯非对称?</strong></p><p>纯非对称太慢(大数运算);纯对称密钥分发不安全。混合:非对称只<strong>安全交换</strong>对称密钥(少量、慢没关系),大数据走对称(快),取长补短。</p><p><strong>Q2:证书怎么防止&quot;中间人&quot;伪造?</strong></p><p>① 证书由受信任 <strong>CA 签名</strong>;② 伪造者自建证书 → 根证书不受信任 → 浏览器告警;③ 篡改证书内容 → 签名校验不过;④ 冒充域名 → 拿不到合法证书。</p><p><strong>Q3:HTTP/2 的&quot;多路复用&quot;解决什么?</strong></p><p>HTTP/1.1 同连接请求<strong>串行</strong>、有队头阻塞;HTTP/2 用<strong>二进制分帧</strong>在同一条 TCP 上<strong>并发多流</strong>,消除队头阻塞、减连接数。(根治丢包级阻塞要 HTTP/3 的 QUIC。)</p><p><strong>Q4:TLS 握手的核心步骤?</strong></p><p>① ClientHello(版本/套件/随机数);② ServerHello + 证书;③ 客户端验证书、生成密钥交换参数;④ 双方算出会话密钥;⑤ Finished,之后对称加密通信。</p><p><strong>Q5:HTTPS 能保证绝对安全吗?</strong></p><p>不能。HTTPS 保&quot;<strong>传输安全</strong>&quot;(加密、防篡改、防冒充),但不防:终端被入侵、证书私钥泄露、恶意 CA 签发假证书、以及应用层逻辑漏洞(CSRF/XSS 等)。它是传输层安全,不是&quot;万能安全&quot;。</p><p><strong>Q6:<code>TLS 1.3</code> 相比 1.2 有哪些改进?</strong></p><p>① <strong>握手从 2-RTT 降到 1-RTT</strong>(0-RTT 会话恢复);② 删掉不安全的旧加密套件(RSA 密钥交换);③ 更安全、更快。是当前主流标准。</p><hr><p>📎 参考:MDN《HTTPS》《TLS》、RFC 8446(TLS 1.3)、Google Developers《HTTP/3》</p>`,23))])}const _=d(i,[["render",p]]);export{S as __pageData,_ as default};
